const keyHref = (k) => (typeof k === 'string' ? k : k.url);
caches
  .open(MUSIC)
  .then((c) => c.keys())
  .then((keys) => keys.forEach((k) => cached.add(keyHref(k))))
  .catch(() => undefined)
  .then(() => (listed = true));

/** The cached track, or undefined. */
function cachedTrack(href) {
  return caches.open(MUSIC).then((c) => c.match(href, { ignoreSearch: true, ignoreVary: true }));
}

/** The whole track, from the music cache or fetched once into it. */
function track(href) {
  return caches.open(MUSIC).then((c) =>
    c.match(href, { ignoreSearch: true, ignoreVary: true }).then((hit) => {
      if (hit) return hit;
      let p = inflight.get(href);
      if (!p) {
        p = fetch(href)
          .then((r) => {
            if (r.status !== 200) return r;
            return c
              .put(href, r.clone())
              .then(() => {
                cached.add(href);
                return c.keys();
              })
              .then((keys) =>
                Promise.all(
                  keys.slice(0, Math.max(0, keys.length - MUSIC_MAX)).map((k) => {
                    cached.delete(keyHref(k));
                    return c.delete(k);
                  })
                )
              )
              .then(() => r, () => r);
          })
          .finally(() => inflight.delete(href));
        inflight.set(href, p);
      }
      return p.then((r) => r.clone());
    })
  );
}

/** A Range request answered from the whole track: its slice (206), else the whole. */
function ranged(req, res) {
  const m = /^bytes=(\d*)-(\d*)$/.exec((req.headers && req.headers.get('range')) || '');
  if (!m || res.status !== 200) return res;
  return res.blob().then((blob) => {
    const size = blob.size;
    let start = m[1] === '' ? Math.max(0, size - Number(m[2])) : Number(m[1]);
    let end = m[1] === '' || m[2] === '' ? size - 1 : Math.min(Number(m[2]), size - 1);
    if (!(start <= end && start < size)) {
      return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + size } });
    }
    return new Response(blob.slice(start, end + 1), {
      status: 206,
      headers: {
        'Content-Type': res.headers.get('Content-Type') || 'audio/mp4',
        'Content-Range': 'bytes ' + start + '-' + end + '/' + size,
        'Content-Length': String(end - start + 1),
        'Accept-Ranges': 'bytes',
      },
    });
  });
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      cache.addAll(FILES.map((f) => new Request(new URL(f, self.registration.scope), { cache: 'reload' })))
    )
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys.filter((k) => k.startsWith('erynd-var-') && k !== CACHE && k !== MUSIC).map((k) => caches.delete(k))
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith(MUSIC_DIR)) {
    url.search = '';
    const href = url.href;
    const range = req.headers && req.headers.get('range');
    if (range && listed && !cached.has(href)) {
      // Its first play: the browser's own request, streamed; the whole track cached meanwhile.
      event.waitUntil(track(href).then(() => undefined, () => undefined));
      return;
    }
    let behind = Promise.resolve();
    const answer = cachedTrack(href).then((hit) => {
      if (hit) return ranged(req, hit);
      if (!range) return track(href);
      behind = track(href);
      return fetch(req);
    });
    event.respondWith(answer.catch(() => fetch(req)));
    event.waitUntil(answer.then(() => behind, () => undefined).then(() => undefined, () => undefined));
    return;
  }
  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req).catch(() =>
        caches.open(CACHE).then((c) => c.match(SHELL, { ignoreVary: true })).then((r) => r || Response.error())
      )
    );
    return;
  }
  event.respondWith(
    caches
      .open(CACHE)
      .then((c) => c.match(req, { ignoreSearch: true, ignoreVary: true }))
      .then((hit) => hit || fetch(req))
  );
});
